/**
 * Unit tests for DeserializationConfig#initialize
 */
public class DeserializationConfig_initialize_TriageGen1Test {

    private BaseSettings baseSettings;
    private SubtypeResolver subtypeResolver;
    private SimpleMixInResolver mixins;
    private RootNameLookup rootNames;
    private JsonParser mockParser;

    @Before
    public void setUp() {
        baseSettings = mock(BaseSettings.class);
        subtypeResolver = mock(SubtypeResolver.class);
        mixins = mock(SimpleMixInResolver.class);
        rootNames = mock(RootNameLookup.class);
        mockParser = mock(JsonParser.class);
    }

    /**
     * Test Case 1: Both parser features and format features are zero (no changes).
     * This covers the case where both 'if' conditions are false.
     */
    @Test
    public void testInitialize_NoFeaturesToChange() {
        // Using a subclass or a way to instantiate since constructor is protected/complex
        // DeserializationConfig is typically instantiated via Mapper/ObjectMapper
        // We use a mock-like approach or a concrete implementation if available.
        // Given the context, we will use a spy or a concrete implementation if possible.

        DeserializationConfig config = new StdDeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames);

        config.initialize(mockParser);

        verify(mockParser, never()).overrideStdFeatures(anyInt(), anyInt());
        verify(mockParser, never()).overrideFormatFeatures(anyInt(), anyInt());
    }

    /**
     * Test Case 2: Only parser features need to be changed.
     * This covers the branch where _parserFeaturesToChange != 0 and _formatReadFeaturesToChange == 0.
     */
    @Test
    public void testInitialize_OnlyParserFeaturesToChange() {
        // We need to trigger the state where _parserFeaturesToChange != 0
        // Since we cannot set private fields directly, we use the 'with' methods 
        // provided in the class description to modify the state.

        DeserializationConfig config = new StdDeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames)
                .with(JsonParser.Feature.AUTO_CLOSE_SOURCE); // This should trigger _parserFeaturesToChange

        config.initialize(mockParser);

        // Verify overrideStdFeatures was called
        // We don't know the exact mask, so we use anyInt()
        verify(mockParser, atLeastOnce()).overrideStdFeatures(anyInt(), anyInt());
        // Verify overrideFormatFeatures was NOT called (assuming no format features were added)
        verify(mockParser, never()).overrideFormatFeatures(anyInt(), anyInt());
    }

    /**
     * Test Case 3: Only format features need to be changed.
     * This covers the branch where _parserFeaturesToChange == 0 and _formatReadFeaturesToChange != 0.
     */
    @Test
    public void testInitialize_OnlyFormatFeaturesToChange() {
        // Use 'with' to set a FormatFeature
        // We use a dummy FormatFeature if available via the API
        // Note: In Jackson, FormatFeature is an interface/enum-like structure

        // Since we don't have the exact enum constant here, we assume the 'with' method 
        // correctly sets the internal _formatReadFeatures and _formatReadFeaturesToChange.

        // We use a mock for FormatFeature if necessary, but usually, these are enums.
        // Let's assume we can trigger it via the 'with' method.

        // For the purpose of this test, we'll use a mock to represent the feature if it's not easily accessible,
        // but standard practice is using the provided 'with' methods.

        // Creating a config and adding a format feature
        // Using a dummy feature if possible. Here we assume the 'with' logic works.
        DeserializationConfig config = new StdDeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames)
                .with(mock(FormatFeature.class)); 

        config.initialize(mockParser);

        // Verify overrideFormatFeatures was called
        verify(mockParser, atLeastOnce()).overrideFormatFeatures(anyInt(), anyInt());
    }

    /**
     * Test Case 4: Both parser features and format features need to be changed.
     * This covers the branch where both 'if' conditions are true.
     */
    @Test
    public void testInitialize_BothFeaturesToChange() {
        DeserializationConfig config = new StdDeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames)
                .with(JsonParser.Feature.AUTO_CLOSE_SOURCE)
                .with(mock(FormatFeature.class));

        config.initialize(mockParser);

        verify(mockParser, atLeastOnce()).overrideStdFeatures(anyInt(), anyInt());
        verify(mockParser, atLeastOnce()).overrideFormatFeatures(anyInt(), anyInt());
    }
}
